function validate(input) {
  const [{ Orders = [], Items = [] }] = input;
  const items = new Set(), orders = new Set();
  for (const [id, name, category] of Items) {
    if (id === null || category === null) return 'Every item needs an item_id and an item_category.';
    if (items.has(id)) return `item_id ${id} appears twice in Items.`;
    items.add(id);
  }
  for (const [order, customer, date, item, quantity] of Orders) {
    if (order === null || customer === null || date === null || item === null || quantity === null) return 'Orders values cannot be null.';
    const key = `${order}|${item}`;
    if (orders.has(key)) return `(order_id, item_id) (${order}, ${item}) appears twice.`;
    orders.add(key);
    if (!items.has(item)) return `Order ${order} names item ${item}, which is not in Items.`;
    if (quantity < 1) return 'quantity must be positive.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `order_date ${date} is not YYYY-MM-DD.`;
  }
  return null;
}

