function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const categories = small ? ['Book', 'Phone', 'Glasses', 'T-shirt'] : ['Book', 'Phone', 'Glasses', 'T-shirt', 'Toys', 'Garden', 'Kitchen', 'Music', 'Sports', 'Shoes'];
  const itemCount = small ? pick(7) : 300, orderCount = itemCount === 0 ? 0 : small ? pick(9) : 1700;
  const span = small ? 15 : 400;
  const Items = [], Orders = [];
  for (let id = 1; id <= itemCount; id++) Items.push([String(id), `Item ${id}`, categories[pick(categories.length)]]);
  const base = Date.UTC(2020, 5, 1);
  const day = k => new Date(base + k * 86400000).toISOString().slice(0, 10);
  for (let id = 1; id <= orderCount; id++) {
    Orders.push([id, 1 + pick(small ? 5 : 200), day(pick(span)), String(1 + pick(itemCount)), 1 + pick(small ? 10 : 50)]);
  }
  return [{ Orders, Items }];
}
